<script lang="ts">
 import {modeLabel,type PromptMode} from '../ai/modes';
 let {value,onchoose,disabled=false,discovery=false}:{value:PromptMode;onchoose:(mode:PromptMode)=>void;disabled?:boolean;discovery?:boolean}=$props();
